inline bool in(float u, float v) {
  int c = (int)(u * COLS); if (c < 0) c = 0; else if (c >= COLS) c = COLS - 1;
  int r = (int)(v * ROWS); if (r < 0) r = 0; else if (r >= ROWS) r = ROWS - 1;
  return GRID[r * COLS + c] != 0;
}
